import{c as r,Q as d,j as o,m as i}from"./chunks/framework.BIK1AyNB.js";const c=JSON.parse('{"title":"🗺️ 地图攻略","description":"","frontmatter":{},"headers":[],"relativePath":"maps/index.md","filePath":"maps/index.md","lastUpdated":1778833334000}'),l={name:"maps/index.md"};function s(a,t,n,e,g,h){return d(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="🗺️-地图攻略" tabindex="-1">🗺️ 地图攻略 <a class="header-anchor" href="#🗺️-地图攻略" aria-label="Permalink to &quot;🗺️ 地图攻略&quot;">​</a></h1><p>Knox Country 共有 <strong>5 个主要城镇</strong>，以及若干野外/郊区区域。</p><h2 id="城镇概览" tabindex="-1">城镇概览 <a class="header-anchor" href="#城镇概览" aria-label="Permalink to &quot;城镇概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>城镇</th><th>规模</th><th>僵尸密度</th><th>特色资源</th><th>推荐出生</th></tr></thead><tbody><tr><td>Muldraugh</td><td>中</td><td>中-高</td><td>大型仓库群、书店、五金店</td><td>✅ 万能起手</td></tr><tr><td>West Point</td><td>中</td><td>高</td><td>枪店、五金店、高中</td><td>❌ 新手慎选</td></tr><tr><td>Riverside</td><td>中</td><td>中</td><td>学校图书馆、汽修店、五金店</td><td>✅ 新手友好</td></tr><tr><td>Rosewood</td><td>小</td><td>低</td><td>消防局、警察局、法院</td><td>✅ 新手首选</td></tr><tr><td>March Ridge</td><td>中</td><td>高</td><td>军事公寓、学校图书馆</td><td>❌ 物资少僵尸多</td></tr><tr><td>Valley Station</td><td>小</td><td>极低</td><td>大卖场、枪店</td><td>✅ 郊区安逸</td></tr></tbody></table><h2 id="详细城镇分析" tabindex="-1">详细城镇分析 <a class="header-anchor" href="#详细城镇分析" aria-label="Permalink to &quot;详细城镇分析&quot;">​</a></h2><h3 id="rosewood-🏡-—-新手港湾" tabindex="-1">Rosewood 🏡 — 新手港湾 <a class="header-anchor" href="#rosewood-🏡-—-新手港湾" aria-label="Permalink to &quot;Rosewood 🏡 — 新手港湾&quot;">​</a></h3><ul><li><strong>僵尸密度</strong>: 低</li><li><strong>核心资源</strong>: <ul><li>🪓 <strong>消防局</strong> — 斧头、消防服、医疗包（城镇东北角）</li><li>👮 <strong>警察局</strong> — 枪械和弹药（城镇南部）</li><li>📚 <strong>法院图书馆</strong> — 技能书（镇中心）</li><li>🏥 <strong>诊所</strong> — 医疗物资（镇中心）</li></ul></li><li><strong>推荐安全屋</strong>: 消防局二楼（自带厨房、冰箱、坚固墙壁）</li><li><strong>缺点</strong>: 没有五金店，木工材料依赖拆家具</li></ul><h3 id="riverside-🏞️-—-均衡小镇" tabindex="-1">Riverside 🏞️ — 均衡小镇 <a class="header-anchor" href="#riverside-🏞️-—-均衡小镇" aria-label="Permalink to &quot;Riverside 🏞️ — 均衡小镇&quot;">​</a></h3><ul><li><strong>僵尸密度</strong>: 中</li><li><strong>核心资源</strong>: <ul><li>📚 <strong>学校</strong> — 海量书架，一把搜满技能书</li><li>🔧 <strong>五金店</strong> — 木工和机械工具（主街）</li><li>🚗 <strong>汽修店</strong> — 车辆零件（镇东）</li><li>🏪 <strong>药店 + 诊所</strong> — 医疗物资（主街）</li><li>⛽ <strong>加油站</strong> — 有两个（西南和西北）</li></ul></li><li><strong>推荐安全屋</strong>: 河边酒吧二楼（靠近水源、钓鱼方便、远离密集区）</li></ul><h3 id="muldraugh-🏙️-—-仓库天堂" tabindex="-1">Muldraugh 🏙️ — 仓库天堂 <a class="header-anchor" href="#muldraugh-🏙️-—-仓库天堂" aria-label="Permalink to &quot;Muldraugh 🏙️ — 仓库天堂&quot;">​</a></h3><ul><li><strong>僵尸密度</strong>: 中-高（主公路沿线非常高！）</li><li><strong>核心资源</strong>: <ul><li>📦 <strong>大型仓库 x4</strong> — 南端两个 + 中南部两个，海量金属加工和木工材料</li><li>📚 <strong>Enigma Books</strong> — 全图唯一的专门书店，技能书天堂</li><li>🔧 <strong>五金店</strong> — 主街中段</li><li>👮 <strong>警察局</strong> — 主街北段</li></ul></li><li><strong>推荐安全屋</strong>: 南部仓库区（自带工业货架、空间巨大，但要清干净周围）</li><li><strong>警告</strong>: 主公路是游戏中僵尸密度最高的区域之一，白天横穿务必小心</li></ul><h3 id="west-point-💀-—-死亡陷阱" tabindex="-1">West Point 💀 — 死亡陷阱 <a class="header-anchor" href="#west-point-💀-—-死亡陷阱" aria-label="Permalink to &quot;West Point 💀 — 死亡陷阱&quot;">​</a></h3><ul><li><strong>僵尸密度</strong>: 高-极高</li><li><strong>核心资源</strong>: <ul><li>🔫 <strong>枪店</strong> — 城镇西部外围</li><li>🏫 <strong>高中</strong> — 大量书架和储物柜</li><li>🔧 <strong>五金店</strong> — 主街中部</li><li>⛽ <strong>加油站</strong> — 镇东</li></ul></li><li><strong>推荐安全屋</strong>: Twiggy&#39;s 酒吧（镇外独立建筑，僵尸少）</li><li><strong>警告</strong>: 商业区是游戏中最危险的区域之一。不要在主街开枪 — 几百只会涌过来。</li></ul><h3 id="march-ridge-⚠️-—-死亡小镇" tabindex="-1">March Ridge ⚠️ — 死亡小镇 <a class="header-anchor" href="#march-ridge-⚠️-—-死亡小镇" aria-label="Permalink to &quot;March Ridge ⚠️ — 死亡小镇&quot;">​</a></h3><ul><li><strong>僵尸密度</strong>: 高，且资源稀少</li><li><strong>核心资源</strong>: 社区中心图书馆（大量书架）</li><li><strong>推荐安全屋</strong>: 不推荐在此地建造安全屋。来搜刮技能书后尽快离开。</li><li><strong>特殊建筑</strong>: 军事公寓（2 层大型公寓楼，僵尸极多，但军装和子弹丰富）</li></ul><h2 id="通用重要建筑" tabindex="-1">通用重要建筑 <a class="header-anchor" href="#通用重要建筑" aria-label="Permalink to &quot;通用重要建筑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>建筑类型</th><th>搜刮重点</th><th>到哪找</th></tr></thead><tbody><tr><td>书店/图书馆</td><td>技能书</td><td>Riverside 学校、Muldraugh Enigma Books</td></tr><tr><td>五金店</td><td>锯子、锤子、钉子、螺丝刀</td><td>各城镇主街</td></tr><tr><td>警察局</td><td>枪、子弹、警车</td><td>各城镇中心</td></tr><tr><td>消防局</td><td>斧头、消防服</td><td>Rosewood</td></tr><tr><td>仓库</td><td>木板、钉子、金属、工具</td><td>Muldraugh 南部</td></tr><tr><td>加油站</td><td>汽油（用空桶接）</td><td>各城镇边缘</td></tr><tr><td>诊所/药店</td><td>绷带、止痛药、抗生素</td><td>各城镇</td></tr><tr><td>汽修店</td><td>轮胎、电池、千斤顶</td><td>Riverside、各城镇</td></tr></tbody></table><h2 id="🏠-安全屋选址原则" tabindex="-1">🏠 安全屋选址原则 <a class="header-anchor" href="#🏠-安全屋选址原则" aria-label="Permalink to &quot;🏠 安全屋选址原则&quot;">​</a></h2><ol><li><strong>远离主路</strong> — 减少随机僵尸游荡到门口</li><li><strong>二楼建筑</strong> — 可以用锤子拆楼梯，僵尸永远上不来</li><li><strong>靠近水源</strong> — 河流/湖泊旁边，断电后也能钓鱼喝水</li><li><strong>有围栏</strong> — 预制高围栏能挡住僵尸，省下大量木工</li><li><strong>多出口</strong> — 窗绳逃生至少 3 条</li></ol><div class="tip custom-block"><p class="custom-block-title">公认最佳新手安全屋</p><p><strong>Rosewood 消防局</strong>：坚固围栏环绕 + 自带厨房冰箱 + 二楼可拆楼梯 + 低密度环境。存活到中后期的完美跳板。</p></div>',20)])])}const b=r(l,[["render",s]]);export{c as __pageData,b as default};
